// Loads 13 months + full prior calendar year. Default view = last 13 months.
const cfg = $('Config').first().json;
const months = Number(cfg.lookbackMonths) || 13;
const now = new Date();
const pad = n => (n < 10 ? '0' + n : '' + n);
const fmt = dt => dt.getUTCFullYear() + '-' + pad(dt.getUTCMonth() + 1) + '-' + pad(dt.getUTCDate());
const back = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - months, now.getUTCDate()));
const defaultFrom = fmt(back);
const py = now.getUTCFullYear() - 1;
const priorStart = py + '-01-01';
const priorEnd = py + '-12-31';
const loadStart = (defaultFrom < priorStart) ? defaultFrom : priorStart;
const endDay = fmt(now);
return [{ json: { rangeStart: loadStart + 'T00:00:00Z', rangeEnd: endDay + 'T23:59:59Z', startDay: loadStart, endDay: endDay, defaultFrom: defaultFrom, priorStart: priorStart, priorEnd: priorEnd, generatedAt: now.toISOString() } }];

// One record per (instructor, teaching session) - NO NAMES (opaque contact id only). Excludes cancelled.
function hoursOf(a,b){const s=new Date(String(a)+'Z').getTime();const e=new Date(String(b)+'Z').getTime();if(!isFinite(s)||!isFinite(e)||e<=s)return 0;return (e-s)/3600000;}
const edges=[];
for(const item of $input.all()){
  const body=item.json;
  if(body && Array.isArray(body.errors) && body.errors.length){ throw new Error('Administrate GraphQL error: '+JSON.stringify(body.errors)); }
  const e=body && body.data && body.data.events && body.data.events.edges;
  if(Array.isArray(e)) edges.push(...e);
}
const out=[];
for(const ev of edges){
  const evn=ev && ev.node; if(!evn) continue;
  if(String(evn.lifecycleState||'').toLowerCase()==='cancelled') continue;
  const title=evn.title||'(untitled)';
  const sess=(evn.sessions && evn.sessions.edges)||[];
  for(const se of sess){
    const s=se && se.node; if(!s) continue;
    if(String(s.lifecycleState||'').toLowerCase()==='cancelled') continue;
    const staff=(s.staff && s.staff.edges)||[];
    for(const st of staff){
      const sn=st && st.node; if(!sn) continue;
      if(String(sn.staffType||'').toLowerCase()!=='instructor') continue;
      const c=sn.contact||{};
      out.push({ ii: c.id||'?', s: String(s.start).slice(0,10), e: String(s.end).slice(0,10), et: String(s.end).slice(11,19), h: Math.round(hoursOf(s.start,s.end)*100)/100, ev: title });
    }
  }
}
if(out.length===0) return [{ json:{ __empty:true } }];
return out.map(json=>({json}));

// Compress name-free records into a compact payload. No PII: opaque instructor ids + course/date/hours only.
const records = $input.all().map(i => i.json).filter(r => !r.__empty);
const win = $('Build Window').first().json;
const ins = []; const insMap = {};
const crs = []; const crsMap = {};
function iidx(id){ if(insMap[id]===undefined){ insMap[id]=ins.length; ins.push(id); } return insMap[id]; }
function cidx(name){ if(crsMap[name]===undefined){ crsMap[name]=crs.length; crs.push(name); } return crsMap[name]; }
const recs = records.map(function(r){ return [ iidx(r.ii), cidx(r.ev || '(untitled)'), r.s, r.e, r.et, r.h ]; });
const payload = JSON.stringify({ ins: ins, crs: crs, recs: recs, generatedAt: win.generatedAt });
return [{ json: { cacheKey: 'instructor', payload: payload, count: records.length } }];
